static char *pjoin(const char *d, const char *t) {
	size_t n = strlen(t);
	while(n>1 && t[n-1]=='/') n--;
	const char *b = t;
	for(size_t k = 0; k<n; k++) if(t[k]=='/' && k+1<n) b = t+k+1;
	size_t bl = n-(size_t)(b-t);
	size_t dl = strlen(d);
	char *r = (char*)malloc(dl+bl+2);
	memcpy(r, d, dl);
	if(dl && d[dl-1]!='/') r[dl++] = '/';
	memcpy(r+dl, b, bl);
	r[dl+bl] = '\0';
	return r;
}

