static void letab(Code *c, Gen *g) {
	if(g->le_tab) return;
	Buf e, d;
	binit(&e);
	binit(&d);
	uint16_t off[136];
	for(int i = 0; i<135; i++) {
		off[i] = (uint16_t)(272+d.len);
		const char *m = strerror(i);
		bput(&d, m, strlen(m));
	}
	off[135] = (uint16_t)(272+d.len);
	bput(&e, off, 272);
	bput(&e, d.data, d.len);
	g->le_tab = tdata(c, e.data, e.len);
	free(e.data);
	free(d.data);
}

