static void trchk(Code *c, Gen *g, const char *m) {
	c8(c,0x48); c8(c,0x85); c8(c,0xC0);
	size_t js = js_rel32(c);
	size_t je = jmp_rel32(c);
	patch_here(c,js);
	rterr(c,g,m);
	patch_here(c,je);
}

static void hdargs(Code *c, uint64_t cnt, uint64_t md, uint64_t dl) {
	c8(c,0x48); c8(c,0xBE); c64(c,cnt);
	c8(c,0x48); c8(c,0xBA); c64(c,md);
	c8(c,0x48); c8(c,0xB9); c64(c,dl);
}

