static void tlargs(Code *c, Gen *g, uint64_t cnt, uint64_t md) {
	c8(c,0x48); c8(c,0xBE); c64(c,cnt);
	c8(c,0x48); c8(c,0xBA); c64(c,md);
	c8(c,0x48); c8(c,0xB9); c64(c,'\n');
	c8(c,0x49); c8(c,0xB8); c64(c,IN_BASE);
	c8(c,0x49); c8(c,0xB9); c64(c,LB_BASE+0x100000);
}

static int tlnum(const char *s, uint64_t *v, int *sign) {
	*sign = 0;
	if(*s=='+' || *s=='-') *sign = *s++=='+' ? 1 : -1;
	return pdig(s, v);
}

