static const char cutu[] = "usage: cut -b list [-n] [file...]\n       cut -c list [file...]\n       cut -f list [-d delim] [-s] [file...]\n";

static int cutl(const char *s, int fm, uint64_t (**rv)[2], int *rn, char *m, size_t ms) {
	const char *what = fm ? "fields are numbered from 1" : "byte/character positions are numbered from 1";
	int n = 0, cap = 8;
	uint64_t (*r)[2] = malloc(sizeof(*r)*(size_t)cap);
	const char *p = s;
	m[0] = '\0';
	for(;;) {
		const char *e = p;
		while(*e && *e!=',' && *e!=' ' && *e!='\t') e++;
		size_t l = (size_t)(e-p);
		char el[256];
		if(l>255) l = 255;
		memcpy(el, p, l);
		el[l] = '\0';
		uint64_t lo = 1, hi = UINT64_MAX;
		char *dash = strchr(el, '-');
		if(!l) snprintf(m, ms, "cut: %s\n", what);
		else if(strcmp(el,"-")==0) snprintf(m, ms, "cut: invalid range with no endpoint: -\n");
		else {
			const char *parts[2] = {el, dash ? dash+1 : NULL};
			if(dash) *dash = '\0';
			for(int k = 0; k<2 && !m[0]; k++) {
				const char *q = parts[k];
				if(!q || !*q) continue;
				const char *t = q;
				while(*t>='0' && *t<='9') t++;
				if(*t) {
					snprintf(m, ms, fm ? "cut: invalid field value %s\n" : "cut: invalid byte/character position %s\n", q);
					break;
				}
				uint64_t v = 0;
				for(t = q; *t; t++) v = v>(UINT64_MAX-9)/10 ? UINT64_MAX : v*10+(uint64_t)(*t-'0');
				if(v==UINT64_MAX) {
					snprintf(m, ms, fm ? "cut: field number %s is too large\n" : "cut: byte/character offset %s is too large\n", q);
					break;
				}
				if(v==0) {
					snprintf(m, ms, "cut: %s\n", what);
					break;
				}
				if(k==0) {
					lo = v;
					if(!dash) hi = v;
				} else hi = v;
			}
			if(!m[0] && lo>hi) snprintf(m, ms, "cut: invalid decreasing range\n");
		}
		if(m[0]) {
			free(r);
			return 0;
		}
		if(n==cap) {
			cap *= 2;
			r = realloc(r, sizeof(*r)*(size_t)cap);
		}
		r[n][0] = lo;
		r[n][1] = hi;
		n++;
		if(!*e) break;
		p = e+1;
	}
	for(int i = 1; i<n; i++) {
		for(int k = i; k>0 && r[k-1][0]>r[k][0]; k--) {
			uint64_t t0 = r[k][0], t1 = r[k][1];
			r[k][0] = r[k-1][0];
			r[k][1] = r[k-1][1];
			r[k-1][0] = t0;
			r[k-1][1] = t1;
		}
	}
	int mn = 0;
	for(int i = 0; i<n; i++) {
		if(mn && r[i][0]<=r[mn-1][1]) {
			if(r[i][1]>r[mn-1][1]) r[mn-1][1] = r[i][1];
		} else {
			r[mn][0] = r[i][0];
			r[mn][1] = r[i][1];
			mn++;
		}
	}
	*rv = r;
	*rn = mn;
	return 1;
}

static const char *cutck(char *o, char **ov, int nl) {
	if(nl>1) return "cut: only one list may be specified\n";
	if(!ov['b'] && !ov['c'] && !ov['f']) return "cut: you must specify a list of bytes, characters, or fields\n";
	if(o['d'] && !ov['f']) return "cut: an input delimiter may be specified only when operating on fields\n";
	if(o['s'] && !ov['f']) return "cut: suppressing non-delimited lines makes sense\n\tonly when operating on fields\n";
	const char *dl = ov['d'] ? ov['d'] : "";
	size_t dlen = strlen(dl);
	if(dlen>1) {
		unsigned char d0 = (unsigned char)dl[0];
		size_t cl = d0<0x80 ? 1 : d0>=0xF0 ? 4 : d0>=0xE0 ? 3 : d0>=0xC0 ? 2 : 0;
		if(cl!=dlen) return "cut: the delimiter must be a single character\n";
	}
	return NULL;
}

