enum { CM_R = 1 };

static void chusage(CS *x, char *m) {
	cerr(x, m);
	cop(x, CO_ERR, xfmt("usage: chmod [-R] mode file...\n"), 0);
	cop(x, CO_EXIT, NULL, 1);
	x->stop = 1;
}

