		us(b, "\ndo\n");
		ulist(b, a->v[0]);
		us(b, "done");
		urd(b, a);
		return;
	case N_ARFOR:
		us(b, "for ((");
		us(b, a->ex[0]);
		b8(b, ';');
		us(b, a->ex[1]);
		b8(b, ';');
		us(b, a->ex[2]);
		us(b, "))\ndo\n");
		if(a->v[0]->k==N_LIST) ulist(b, a->v[0]);
		else {
			ua(b, a->v[0]);
			b8(b, '\n');
		}
		us(b, "done");
		urd(b, a);
		return;
	case N_CASE:
		us(b, "case ");
		uw(b, a->word, 0);
		us(b, " in\n");
		for(int i = 0; i<a->nci; i++) {
			b8(b, '(');
			for(int j = 0; j<a->ci[i].np; j++) {
				if(j) b8(b, '|');
				uw(b, a->ci[i].pat[j], 0);
			}
			us(b, ")\n");
			ulist(b, a->ci[i].body);
			us(b, a->ci[i].ft==1 ? ";&\n" : a->ci[i].ft==2 ? ";;&\n" : ";;\n");
		}
		us(b, "esac");
		urd(b, a);
		return;
	case N_FUNC:
		us(b, a->name);
		us(b, "() ");
		ua(b, a->v[0]);
		return;
	case N_ARITH:
		us(b, "((");
		us(b, a->ex[0]);
		us(b, "))");
		urd(b, a);
		return;
	case N_DBRK:
		us(b, "[[");
		for(int i = 0; i<a->nw; i++) {
			b8(b, ' ');
			uw(b, a->w[i], 0);
		}
