typedef struct {
	Buf b;
	size_t *rl;
	size_t nr, cr;
} Sz;

#define SZNIL ((size_t)-1)

static void szrel(Sz *z, size_t at) {
	if(z->nr==z->cr) {
		z->cr = z->cr ? z->cr*2 : 256;
		z->rl = realloc(z->rl, sizeof(size_t)*z->cr);
	}
	z->rl[z->nr++] = at;
}

static size_t szput(Sz *z, const void *p, size_t n) {
	while(z->b.len & 7) b8(&z->b, 0);
	size_t o = z->b.len;
	bput(&z->b, p, n);
	return o;
}

static size_t szzero(Sz *z, size_t n) {
	while(z->b.len & 7) b8(&z->b, 0);
	size_t o = z->b.len;
	for(size_t i = 0; i<n; i++) b8(&z->b, 0);
	return o;
}

static void szset(Sz *z, size_t at, size_t t) {
	uint64_t v = t==SZNIL ? 0 : t;
	memcpy(z->b.data+at, &v, 8);
	if(t!=SZNIL) szrel(z, at);
}

static size_t szs(Sz *z, const char *s) {
	if(!s) return SZNIL;
	size_t o = z->b.len;
	bput(&z->b, s, strlen(s)+1);
	return o;
}

static size_t szan(Sz *z, An *a);

static size_t szwd(Sz *z, Wd *w) {
	if(!w) return SZNIL;
	size_t *ps = w->n ? calloc((size_t)w->n, sizeof(size_t)*8) : NULL;
	for(int i = 0; i<w->n; i++) {
		Wp *p = &w->p[i];
		size_t *q = ps+i*8;
		q[0] = szs(z, p->s);
		q[1] = szs(z, p->op);
		q[2] = szwd(z, p->arg);
		q[3] = szwd(z, p->arg2);
		q[4] = p->cmd ? szan(z, p->cmd) : SZNIL;
		q[5] = SZNIL;
		if(p->ndq) {
			size_t *dv = calloc((size_t)p->ndq, sizeof(size_t));
			for(int k = 0; k<p->ndq; k++) dv[k] = szwd(z, p->dq[k]);
			q[5] = szzero(z, sizeof(Wd*)*(size_t)p->ndq);
			for(int k = 0; k<p->ndq; k++) szset(z, q[5]+8*(size_t)k, dv[k]);
			free(dv);
		}
	}
	size_t pa = SZNIL;
	if(w->n) {
		pa = szput(z, w->p, sizeof(Wp)*(size_t)w->n);
		for(int i = 0; i<w->n; i++) {
			size_t b = pa+sizeof(Wp)*(size_t)i, *q = ps+i*8;
			szset(z, b+offsetof(Wp, s), q[0]);
			szset(z, b+offsetof(Wp, op), q[1]);
			szset(z, b+offsetof(Wp, arg), q[2]);
			szset(z, b+offsetof(Wp, arg2), q[3]);
			szset(z, b+offsetof(Wp, cmd), q[4]);
			szset(z, b+offsetof(Wp, dq), q[5]);
		}
	}
	free(ps);
	size_t raw = szs(z, w->raw);
	Wd c = *w;
	c.cap = c.n;
	size_t o = szput(z, &c, sizeof(Wd));
	szset(z, o+offsetof(Wd, p), pa);
	szset(z, o+offsetof(Wd, raw), raw);
	return o;
}

static size_t szwv(Sz *z, Wd **v, int n) {
	if(!n) return SZNIL;
	size_t *t = calloc((size_t)n, sizeof(size_t));
	for(int i = 0; i<n; i++) t[i] = szwd(z, v[i]);
	size_t o = szzero(z, sizeof(Wd*)*(size_t)n);
	for(int i = 0; i<n; i++) szset(z, o+8*(size_t)i, t[i]);
	free(t);
	return o;
}

static size_t szan(Sz *z, An *a) {
	if(!a) return SZNIL;
	size_t *cv = a->n ? calloc((size_t)a->n, sizeof(size_t)) : NULL;
	for(int i = 0; i<a->n; i++) cv[i] = szan(z, a->v[i]);
	size_t vv = SZNIL;
	if(a->n) {
		vv = szzero(z, sizeof(An*)*(size_t)a->n);
		for(int i = 0; i<a->n; i++) szset(z, vv+8*(size_t)i, cv[i]);
	}
	free(cv);
	size_t as = szwv(z, a->as, a->nas), ws = szwv(z, a->w, a->nw);
	size_t rd = SZNIL;
	if(a->nrd) {
		size_t *rw = calloc((size_t)a->nrd*2, sizeof(size_t));
		for(int i = 0; i<a->nrd; i++) {
			rw[2*i] = szwd(z, a->rd[i].w);
			rw[2*i+1] = szs(z, a->rd[i].body);
		}
		rd = szput(z, a->rd, sizeof(Rd)*(size_t)a->nrd);
		for(int i = 0; i<a->nrd; i++) {
			size_t b = rd+sizeof(Rd)*(size_t)i;
			szset(z, b+offsetof(Rd, w), rw[2*i]);
			szset(z, b+offsetof(Rd, body), rw[2*i+1]);
		}
		free(rw);
	}
	size_t ci = SZNIL;
	if(a->nci) {
		size_t *cp = calloc((size_t)a->nci*2, sizeof(size_t));
		for(int i = 0; i<a->nci; i++) {
			cp[2*i] = szwv(z, a->ci[i].pat, a->ci[i].np);
			cp[2*i+1] = szan(z, a->ci[i].body);
		}
		ci = szput(z, a->ci, sizeof(Ci)*(size_t)a->nci);
		for(int i = 0; i<a->nci; i++) {
			size_t b = ci+sizeof(Ci)*(size_t)i;
			szset(z, b+offsetof(Ci, pat), cp[2*i]);
			szset(z, b+offsetof(Ci, body), cp[2*i+1]);
		}
		free(cp);
	}
	size_t nm = szs(z, a->name), wd = szwd(z, a->word);
	size_t ex[3], exw[3];
	for(int i = 0; i<3; i++) ex[i] = szs(z, a->ex[i]);
	for(int i = 0; i<3; i++) exw[i] = szwd(z, a->exw[i]);
	An c = *a;
	c.cap = c.n;
	size_t o = szput(z, &c, sizeof(An));
	szset(z, o+offsetof(An, v), vv);
	szset(z, o+offsetof(An, as), as);
	szset(z, o+offsetof(An, w), ws);
	szset(z, o+offsetof(An, rd), rd);
	szset(z, o+offsetof(An, name), nm);
	szset(z, o+offsetof(An, word), wd);
	szset(z, o+offsetof(An, ci), ci);
	for(int i = 0; i<3; i++) szset(z, o+offsetof(An, ex)+8*(size_t)i, ex[i]);
	for(int i = 0; i<3; i++) szset(z, o+offsetof(An, exw)+8*(size_t)i, exw[i]);
	return o;
}
